(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit22-trap-c2-advanced-1"]={"id":"unit22-trap-c2-advanced-1","unitId":"2-2","chapterIds":["2-2"],"unitType":"advanced","group":"선지 변형 유형 · 인과","name":"심화 5지선다 1","level":"심화","desc":"2-2단원 · 인과","revision":1,"originPage":"unit22","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"인과","parts":[{"name":"U22-09 · 대리 줄 서기 사업의 등장","items":[{"paragraphCount":1,"readingLabel":"2문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 2문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 2문단]\n많은 뉴요커들은 연극을 보고 싶었으나 줄을 설 시간이 없었다. 이런 곤란한 상황에서 작은 사업거리가 새로 등장했다. 편리를 얻는 대가로 기꺼이 비용을 지불할 의사가 있는 사람을 위해 대신 줄을 서고 입장권을 받아 주는 사업이었다. 이들은 온라인 사이트에 자신들의 서비스를 광고했고, 줄을 서서 기다리는 수고를 견뎌 내는 대가로 무료 공연 입장권에 한 장당 125달러의 수고비를 청구했다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["인과"],"id":"U22-09-S1","type":"mc","sent":"2문단의 내용과 맞는 설명은?","options":["공연은 보고 싶지만 줄을 설 마음이 없는 사람들이 있었다.","대리 줄 서기 사업자는 돈을 받지 않고 표를 받아 준다.","대리 줄 서기 사업자는 극장의 좌석 수를 늘려 준다.","공연을 보고 싶어도 줄 설 시간이 없는 사람들이 있었다. 돈을 받고 대신 줄을 서서 표를 받아 주는 사업이 생겼다.","대리 줄 서기를 이용한 사람들은 공연을 볼 생각이 없었다."],"answer":"공연을 보고 싶어도 줄 설 시간이 없는 사람들이 있었다. 돈을 받고 대신 줄을 서서 표를 받아 주는 사업이 생겼다.","why":"공연을 보고 싶은 마음은 있지만 기다릴 시간이 부족한 사람들이 있었어요. 사업자는 돈을 받고 그 사람들 대신 줄을 섰어요.\n2문단에서 확인할 수 있어요.","choiceReviews":{"공연을 보고 싶어도 줄 설 시간이 없는 사람들이 있었다. 돈을 받고 대신 줄을 서서 표를 받아 주는 사업이 생겼다.":{"reason":"공연을 보고 싶은 마음은 있지만 기다릴 시간이 부족한 사람들이 있었어요. 사업자는 돈을 받고 그 사람들 대신 줄을 섰어요.\n2문단에서 확인할 수 있어요.","edits":[]},"공연은 보고 싶지만 줄을 설 마음이 없는 사람들이 있었다.":{"reason":"바르게 고치면: 공연은 보고 싶지만 줄을 설 시간이 없는 사람들이 있었다.\n공연을 보고 싶은 마음은 있지만 기다릴 시간이 부족한 사람들이 있었어요. 사업자는 돈을 받고 그 사람들 대신 줄을 섰어요.\n2문단에서 확인할 수 있어요.","edits":[{"start":16,"end":20,"before":"마음이 ","after":"시간이 "}]},"대리 줄 서기 사업자는 돈을 받지 않고 표를 받아 준다.":{"reason":"바르게 고치면: 대리 줄 서기 사업자는 돈을 받고 표를 받아 준다.\n공연을 보고 싶은 마음은 있지만 기다릴 시간이 부족한 사람들이 있었어요. 사업자는 돈을 받고 그 사람들 대신 줄을 섰어요.\n2문단에서 확인할 수 있어요.","edits":[{"start":16,"end":22,"before":"받지 않고 ","after":"받고 "}]},"대리 줄 서기 사업자는 극장의 좌석 수를 늘려 준다.":{"reason":"바르게 고치면: 대리 줄 서기 사업자는 대신 줄을 서서 표를 받아 준다.\n공연을 보고 싶은 마음은 있지만 기다릴 시간이 부족한 사람들이 있었어요. 사업자는 돈을 받고 그 사람들 대신 줄을 섰어요.\n2문단에서 확인할 수 있어요.","edits":[{"start":13,"end":26,"before":"극장의 좌석 수를 늘려 ","after":"대신 줄을 서서 표를 받아 "}]},"대리 줄 서기를 이용한 사람들은 공연을 볼 생각이 없었다.":{"reason":"바르게 고치면: 대리 줄 서기를 이용한 사람들은 공연을 보고 싶어 했다.\n공연을 보고 싶은 마음은 있지만 기다릴 시간이 부족한 사람들이 있었어요. 사업자는 돈을 받고 그 사람들 대신 줄을 섰어요.\n2문단에서 확인할 수 있어요.","edits":[{"start":22,"end":32,"before":"볼 생각이 없었다.","after":"보고 싶어 했다."}]}},"pageSpecificReasons":true,"evidence":{"title":"대리 줄 서기 사업의 등장","statement":"공연을 보고 싶어도 줄 설 시간이 없는 사람들이 있었다. 돈을 받고 대신 줄을 서서 표를 받아 주는 사업이 생겼다.","explanation":"공연을 보고 싶은 마음은 있지만 기다릴 시간이 부족한 사람들이 있었어요. 사업자는 돈을 받고 그 사람들 대신 줄을 섰어요.\n2문단에서 확인할 수 있어요.","valid":["L02:1","L02:3"],"sources":[{"id":"L02","title":"줄 서기를 돈으로 살 수 있을까","label":"2문단","sentences":[{"id":"L02:1","text":"많은 뉴요커들은 연극을 보고 싶었으나 줄을 설 시간이 없었다.","paragraph":0,"memberIds":["L02:1"],"topic":"연극을 보고 싶은 뉴욕 사람은 많았다. 그런데 바빠서 줄 설 시간이 없었다."},{"id":"L02:2","text":"이런 곤란한 상황에서 작은 사업거리가 새로 등장했다.","paragraph":0,"memberIds":["L02:2"],"topic":"그러자 새로운 작은 사업이 생겼다."},{"id":"L02:3","text":"편리를 얻는 대가로 기꺼이 비용을 지불할 의사가 있는 사람을 위해 대신 줄을 서고 입장권을 받아 주는 사업이었다.","paragraph":0,"memberIds":["L02:3"],"topic":"어떤 사람들은 돈을 내서라도 편하게 표를 받고 싶었다. 그 사람 대신 줄을 서서 표를 받아다 주는 일이었다."},{"id":"L02:4","text":"이들은 온라인 사이트에 자신들의 서비스를 광고했고, 줄을 서서 기다리는 수고를 견뎌 내는 대가로 무료 공연 입장권에 한 장당 125달러의 수고비를 청구했다.","paragraph":0,"memberIds":["L02:4"],"topic":"이 사람들은 인터넷에 광고를 올렸다. 그리고 공짜 표 한 장을 받아 주는 값으로 125달러(우리 돈 십수만 원)를 달라고 했다(청구했다). 줄 서서 기다린 고생값(수고비)이라는 것이다."}]}]},"editorSourceVersion":"53f2036176652d800a4afef9f85025443f1d91c5f19d49937d4a95c7c916c35a"}]},{"name":"U22-16 · 암표 금지법에 반대하는 이유","items":[{"paragraphCount":1,"readingLabel":"4문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 4문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 4문단]\n줄 서기에 관해 시장을 옹호하는 입장에는 두 가지 주장이 있다. 하나는 개인의 자유 존중에 대한 것이고, 다른 하나는 행복이나 사회적 효용의 극대화에 대한 주장이다. 첫 번째는 자유 지상주의자의 입장이다. 그들은 타인의 권리를 침범하지 않는 한 원하는 재화는 무엇이든 자유롭게 사고팔 수 있어야 한다고 주장한다. 자유 지상주의자는 장기 매매 금지법에 반대하는 것과 같은 이유로 암표 매매 금지법에 반대한다. 이러한 법은 성인이 상호 동의에 따라 내린 선택을 방해함으로써 개인의 자유를 침해한다고 믿기 때문이다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["인과"],"id":"U22-16-S1","type":"mc","sent":"4문단의 내용과 맞는 설명은?","options":["자유 지상주의자는 암표 금지법에 반대한다. 서로 동의한 어른들의 거래를 막으면 개인의 자유를 해친다고 보기 때문이다.","자유 지상주의자는 암표 금지법에 찬성한다.","자유 지상주의자는 암표 금지법이 사회 전체의 이익을 늘리기 때문에 반대한다.","자유 지상주의자가 지키려는 거래는 한 사람이 다른 사람에게 억지로 시킨 거래다.","이 문단에서는 미성년자들의 거래를 막는 일을 문제 삼는다."],"answer":"자유 지상주의자는 암표 금지법에 반대한다. 서로 동의한 어른들의 거래를 막으면 개인의 자유를 해친다고 보기 때문이다.","why":"물건을 파는 어른과 사는 어른이 모두 동의했다면 스스로 선택한 거래예요. 자유 지상주의자는 법으로 이런 거래를 막으면 개인의 자유를 해친다고 봐요.\n4문단에서 확인할 수 있어요.","choiceReviews":{"자유 지상주의자는 암표 금지법에 반대한다. 서로 동의한 어른들의 거래를 막으면 개인의 자유를 해친다고 보기 때문이다.":{"reason":"물건을 파는 어른과 사는 어른이 모두 동의했다면 스스로 선택한 거래예요. 자유 지상주의자는 법으로 이런 거래를 막으면 개인의 자유를 해친다고 봐요.\n4문단에서 확인할 수 있어요.","edits":[]},"자유 지상주의자는 암표 금지법에 찬성한다.":{"reason":"바르게 고치면: 자유 지상주의자는 암표 금지법에 반대한다.\n물건을 파는 어른과 사는 어른이 모두 동의했다면 스스로 선택한 거래예요. 자유 지상주의자는 법으로 이런 거래를 막으면 개인의 자유를 해친다고 봐요.\n4문단에서 확인할 수 있어요.","edits":[{"start":18,"end":23,"before":"찬성한다.","after":"반대한다."}]},"자유 지상주의자는 암표 금지법이 사회 전체의 이익을 늘리기 때문에 반대한다.":{"reason":"바르게 고치면: 자유 지상주의자는 암표 금지법이 개인의 자유를 해치기 때문에 반대한다.\n물건을 파는 어른과 사는 어른이 모두 동의했다면 스스로 선택한 거래예요. 자유 지상주의자는 법으로 이런 거래를 막으면 개인의 자유를 해친다고 봐요.\n4문단에서 확인할 수 있어요.","edits":[{"start":18,"end":33,"before":"사회 전체의 이익을 늘리기 ","after":"개인의 자유를 해치기 "}]},"자유 지상주의자가 지키려는 거래는 한 사람이 다른 사람에게 억지로 시킨 거래다.":{"reason":"바르게 고치면: 자유 지상주의자가 지키려는 거래는 어른들이 서로 동의한 거래다.\n물건을 파는 어른과 사는 어른이 모두 동의했다면 스스로 선택한 거래예요. 자유 지상주의자는 법으로 이런 거래를 막으면 개인의 자유를 해친다고 봐요.\n4문단에서 확인할 수 있어요.","edits":[{"start":19,"end":40,"before":"한 사람이 다른 사람에게 억지로 시킨 ","after":"어른들이 서로 동의한 "}]},"이 문단에서는 미성년자들의 거래를 막는 일을 문제 삼는다.":{"reason":"바르게 고치면: 이 문단에서는 서로 동의한 어른들의 거래를 막는 일을 문제 삼는다.\n물건을 파는 어른과 사는 어른이 모두 동의했다면 스스로 선택한 거래예요. 자유 지상주의자는 법으로 이런 거래를 막으면 개인의 자유를 해친다고 봐요.\n4문단에서 확인할 수 있어요.","edits":[{"start":8,"end":15,"before":"미성년자들의 ","after":"서로 동의한 어른들의 "}]}},"pageSpecificReasons":true,"evidence":{"title":"암표 금지법에 반대하는 이유","statement":"자유 지상주의자는 암표 금지법에 반대한다. 서로 동의한 어른들의 거래를 막으면 개인의 자유를 해친다고 보기 때문이다.","explanation":"물건을 파는 어른과 사는 어른이 모두 동의했다면 스스로 선택한 거래예요. 자유 지상주의자는 법으로 이런 거래를 막으면 개인의 자유를 해친다고 봐요.\n4문단에서 확인할 수 있어요.","valid":["L04:5","L04:6"],"sources":[{"id":"L04","title":"줄 서기를 돈으로 살 수 있을까","label":"4문단","sentences":[{"id":"L04:1","text":"줄 서기에 관해 시장을 옹호하는 입장에는 두 가지 주장이 있다.","paragraph":0,"memberIds":["L04:1"],"topic":"돈으로 줄을 사는 것(시장)에 찬성하는 쪽의 이유는 두 가지다."},{"id":"L04:2","text":"하나는 개인의 자유 존중에 대한 것이고, 다른 하나는 행복이나 사회적 효용의 극대화에 대한 주장이다.","paragraph":0,"memberIds":["L04:2"],"topic":"첫째는 '개인의 자유를 존중하자'는 것이다. 둘째는 '사람들의 만족(효용)을 가장 크게 만들자'는 것이다."},{"id":"L04:3","text":"첫 번째는 자유 지상주의자의 입장이다.","paragraph":0,"memberIds":["L04:3"],"topic":"첫째 이유는 '자유 지상주의자'의 생각이다. 개인의 자유를 무엇보다 중요하게 여기는 사람들이다."},{"id":"L04:4","text":"그들은 타인의 권리를 침범하지 않는 한 원하는 재화는 무엇이든 자유롭게 사고팔 수 있어야 한다고 주장한다.","paragraph":0,"memberIds":["L04:4"],"topic":"그들은 이렇게 말한다. \"남의 권리를 침범하지(피해를 주지) 않는 한, 무엇이든 자유롭게 사고팔 수 있어야 한다.\""},{"id":"L04:5","text":"자유 지상주의자는 장기 매매 금지법에 반대하는 것과 같은 이유로 암표 매매 금지법에 반대한다.","paragraph":0,"memberIds":["L04:5"],"topic":"그래서 그들은 '암표를 팔지 마라'는 법에 반대한다. '장기를 사고팔지 마라'는 법에 반대하는 것과 같은 이유에서다."},{"id":"L04:6","text":"이러한 법은 성인이 상호 동의에 따라 내린 선택을 방해함으로써 개인의 자유를 침해한다고 믿기 때문이다.","paragraph":0,"memberIds":["L04:6"],"topic":"어른 둘이 서로 좋다고 합의한 거래를 법이 막으면, 개인의 자유를 빼앗는 것이라고 믿기 때문이다."}]}]},"editorSourceVersion":"95b35ea43a96738fe024c63135144a7852f20eee30ab63ebbbc6b928290bd054"}]},{"name":"U22-18 · 거래 성립을 근거로 삼는 논리","items":[{"paragraphCount":1,"readingLabel":"5문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 5문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 5문단]\n시장을 옹호하는 두 번째 주장은 경제학자에게 좀 더 친숙한 것으로 공리주의자의 입장이다. 공리주의자는 시장에서의 거래가 구매자와 판매자에게 똑같이 이익을 제공하고, 결과적으로 집단의 행복이나 사회적 효용을 향상한다고 말한다. 돈을 지불한 사람과 돈을 받고 대리로 줄을 선 사람 사이에 거래가 성립했다는 것은 결과적으로 양측이 모두 이익을 얻었다는 뜻이다. 125달러를 내고 대리로 줄을 서 주는 사람을 고용한 사람은 줄을 서지 않고 셰익스피어 연극을 관람함으로써 틀림없이 행복을 느낀다. 그렇지 않다면 애당초 사람을 고용하지 않았을 것이다. 몇 시간 동안 줄을 서서 125달러를 번 사람도 행복을 느낀다. 그렇지 않다면 애당초 그 일을 하지 않았을 것이다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["인과"],"id":"U22-18-S1","type":"mc","sent":"5문단의 내용과 맞는 설명은?","options":["공리주의자는 두 사람에게 이익이 없어도 반드시 거래했을 것이라고 본다.","공리주의자는 거래가 이루어졌으므로 돈을 낸 사람만 손해를 보았다고 설명한다.","공리주의자는 돈을 낸 사람과 대신 줄을 선 사람이 모두 이익을 얻었다고 본다. 이익이 없었다면 처음부터 거래하지 않았을 것이라고 생각하기 때문이다.","거래하면 사는 사람과 파는 사람 모두 이익을 얻는다는 설명은 시장에 반대하는 사람의 생각이다.","공리주의자는 두 사람이 모두 더 행복해질 수 있어도 거래하지 않았을 것이라고 본다."],"answer":"공리주의자는 돈을 낸 사람과 대신 줄을 선 사람이 모두 이익을 얻었다고 본다. 이익이 없었다면 처음부터 거래하지 않았을 것이라고 생각하기 때문이다.","why":"돈을 낸 사람은 기다리는 수고를 덜고, 대신 기다린 사람은 125달러를 받았어요. 공리주의자는 각자 얻는 것이 있으니 스스로 거래했을 것이라고 설명해요.\n5문단에서 확인할 수 있어요.","choiceReviews":{"공리주의자는 돈을 낸 사람과 대신 줄을 선 사람이 모두 이익을 얻었다고 본다. 이익이 없었다면 처음부터 거래하지 않았을 것이라고 생각하기 때문이다.":{"reason":"돈을 낸 사람은 기다리는 수고를 덜고, 대신 기다린 사람은 125달러를 받았어요. 공리주의자는 각자 얻는 것이 있으니 스스로 거래했을 것이라고 설명해요.\n5문단에서 확인할 수 있어요.","edits":[]},"공리주의자는 두 사람에게 이익이 없어도 반드시 거래했을 것이라고 본다.":{"reason":"바르게 고치면: 공리주의자는 두 사람에게 이익이 없었다면 거래하지 않았을 것이라고 본다.\n돈을 낸 사람은 기다리는 수고를 덜고, 대신 기다린 사람은 125달러를 받았어요. 공리주의자는 각자 얻는 것이 있으니 스스로 거래했을 것이라고 설명해요.\n5문단에서 확인할 수 있어요.","edits":[{"start":18,"end":31,"before":"없어도 반드시 거래했을 ","after":"없었다면 거래하지 않았을 "}]},"공리주의자는 거래가 이루어졌으므로 돈을 낸 사람만 손해를 보았다고 설명한다.":{"reason":"바르게 고치면: 공리주의자는 거래가 이루어졌으므로 돈을 낸 사람과 대신 줄을 선 사람 모두 이익을 얻었다고 설명한다.\n돈을 낸 사람은 기다리는 수고를 덜고, 대신 기다린 사람은 125달러를 받았어요. 공리주의자는 각자 얻는 것이 있으니 스스로 거래했을 것이라고 설명해요.\n5문단에서 확인할 수 있어요.","edits":[{"start":24,"end":37,"before":"사람만 손해를 보았다고 ","after":"사람과 대신 줄을 선 사람 모두 이익을 얻었다고 "}]},"거래하면 사는 사람과 파는 사람 모두 이익을 얻는다는 설명은 시장에 반대하는 사람의 생각이다.":{"reason":"바르게 고치면: 거래하면 사는 사람과 파는 사람 모두 이익을 얻는다는 설명은 공리주의자의 생각이다.\n돈을 낸 사람은 기다리는 수고를 덜고, 대신 기다린 사람은 125달러를 받았어요. 공리주의자는 각자 얻는 것이 있으니 스스로 거래했을 것이라고 설명해요.\n5문단에서 확인할 수 있어요.","edits":[{"start":34,"end":47,"before":"시장에 반대하는 사람의 ","after":"공리주의자의 "}]},"공리주의자는 두 사람이 모두 더 행복해질 수 있어도 거래하지 않았을 것이라고 본다.":{"reason":"바르게 고치면: 공리주의자는 두 사람이 더 행복해질 수 없었다면 거래하지 않았을 것이라고 본다.\n돈을 낸 사람은 기다리는 수고를 덜고, 대신 기다린 사람은 125달러를 받았어요. 공리주의자는 각자 얻는 것이 있으니 스스로 거래했을 것이라고 설명해요.\n5문단에서 확인할 수 있어요.","edits":[{"start":13,"end":16,"before":"모두 ","after":""},{"start":25,"end":29,"before":"있어도 ","after":"없었다면 "}]}},"pageSpecificReasons":true,"evidence":{"title":"거래 성립을 근거로 삼는 논리","statement":"공리주의자는 돈을 낸 사람과 대신 줄을 선 사람이 모두 이익을 얻었다고 본다. 이익이 없었다면 처음부터 거래하지 않았을 것이라고 생각하기 때문이다.","explanation":"돈을 낸 사람은 기다리는 수고를 덜고, 대신 기다린 사람은 125달러를 받았어요. 공리주의자는 각자 얻는 것이 있으니 스스로 거래했을 것이라고 설명해요.\n5문단에서 확인할 수 있어요.","valid":["L05:3","L05:4","L05:5","L05:6","L05:7"],"sources":[{"id":"L05","title":"줄 서기를 돈으로 살 수 있을까","label":"5문단","sentences":[{"id":"L05:1","text":"시장을 옹호하는 두 번째 주장은 경제학자에게 좀 더 친숙한 것으로 공리주의자의 입장이다.","paragraph":0,"memberIds":["L05:1"],"topic":"둘째 이유는 '공리주의자'의 생각이다. 경제학자들이 자주 쓰는 생각이다. 공리주의는 '사람들 행복의 합을 가장 크게 만들자'는 생각이다."},{"id":"L05:2","text":"공리주의자는 시장에서의 거래가 구매자와 판매자에게 똑같이 이익을 제공하고, 결과적으로 집단의 행복이나 사회적 효용을 향상한다고 말한다.","paragraph":0,"memberIds":["L05:2"],"topic":"공리주의자는 이렇게 말한다. \"거래를 하면 사는 사람도 이득이고 파는 사람도 이득이다. 그러니 사회 전체의 행복(효용)이 커진다.\""},{"id":"L05:3","text":"돈을 지불한 사람과 돈을 받고 대리로 줄을 선 사람 사이에 거래가 성립했다는 것은 결과적으로 양측이 모두 이익을 얻었다는 뜻이다.","paragraph":0,"memberIds":["L05:3"],"topic":"돈 낸 사람과 대신 줄 선 사람이 거래를 했다. 거래를 했다는 건 결과적으로 둘 다 이익을 얻었다는 뜻이다."},{"id":"L05:4","text":"125달러를 내고 대리로 줄을 서 주는 사람을 고용한 사람은 줄을 서지 않고 셰익스피어 연극을 관람함으로써 틀림없이 행복을 느낀다.","paragraph":0,"memberIds":["L05:4"],"topic":"125달러를 낸 사람은 줄을 안 서고도 연극을 본다. 그러니 분명히 행복하다."},{"id":"L05:5","text":"그렇지 않다면 애당초 사람을 고용하지 않았을 것이다.","paragraph":0,"memberIds":["L05:5"],"topic":"행복하지 않았다면 처음부터 돈을 내지 않았을 것이다."},{"id":"L05:6","text":"몇 시간 동안 줄을 서서 125달러를 번 사람도 행복을 느낀다.","paragraph":0,"memberIds":["L05:6"],"topic":"몇 시간 줄을 서고 125달러를 번 사람도 행복하다."},{"id":"L05:7","text":"그렇지 않다면 애당초 그 일을 하지 않았을 것이다.","paragraph":0,"memberIds":["L05:7"],"topic":"싫었으면 처음부터 그 일을 안 했을 것이다."}]}]},"editorSourceVersion":"820122f78295d4b75586a6eefed4f99939789977ace5dc9fec3bcb9c89bff510"}]},{"name":"U22-27 · 암표 확보가 뒤 사람에게 미치는 영향","items":[{"paragraphCount":1,"readingLabel":"10문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 10문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 10문단]\n아마도 대변인의 의도는 암표 거래는 125달러를 지불할 만한 경제적 여유가 없는 사람에게 불공정한 행위라는 것이리라. 보통 사람은 그만큼 불리하게 되어 입장권을 손에 넣기가 더욱 힘들어진다. 이 주장은 설득력이 있다. 돈을 받고 대신 줄을 선 사람이나 암표상이 입장권을 확보했다면 그 뒤에 서 있던 사람, 즉 암표 가격을 지불할 만한 경제적 여유가 없는 사람은 손해를 본다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["인과"],"id":"U22-27-S1","type":"mc","sent":"10문단의 내용과 맞는 설명은?","options":["암표상이 표를 먼저 가져가면, 뒤에서 기다리던 돈 없는 관객은 이익을 얻는다.","암표상이나 대신 줄을 선 사람이 표를 먼저 받아 가면, 뒤에서 기다리던 관객은 무료 표를 못 받을 수 있다. 암표를 살 돈도 없다면 손해를 본다.","글쓴이가 걱정하는 관객은 암표를 살 돈이 충분한 사람이다.","암표상이 표를 한 장도 받지 않아도, 암표상 때문에 뒤의 관객이 받을 표가 줄어든다.","글쓴이가 걱정하는 관객은 암표상보다 먼저 표를 받은 사람이다."],"answer":"암표상이나 대신 줄을 선 사람이 표를 먼저 받아 가면, 뒤에서 기다리던 관객은 무료 표를 못 받을 수 있다. 암표를 살 돈도 없다면 손해를 본다.","why":"암표상이 먼저 표를 가져가면 뒤에서 기다리는 관객이 받을 표는 줄어들어요. 돈이 부족한 관객은 나중에 암표를 살 수도 없어요.\n10문단에서 확인할 수 있어요.","choiceReviews":{"암표상이나 대신 줄을 선 사람이 표를 먼저 받아 가면, 뒤에서 기다리던 관객은 무료 표를 못 받을 수 있다. 암표를 살 돈도 없다면 손해를 본다.":{"reason":"암표상이 먼저 표를 가져가면 뒤에서 기다리는 관객이 받을 표는 줄어들어요. 돈이 부족한 관객은 나중에 암표를 살 수도 없어요.\n10문단에서 확인할 수 있어요.","edits":[]},"암표상이 표를 먼저 가져가면, 뒤에서 기다리던 돈 없는 관객은 이익을 얻는다.":{"reason":"바르게 고치면: 암표상이 표를 먼저 가져가면, 뒤에서 기다리던 돈 없는 관객은 손해를 본다.\n암표상이 먼저 표를 가져가면 뒤에서 기다리는 관객이 받을 표는 줄어들어요. 돈이 부족한 관객은 나중에 암표를 살 수도 없어요.\n10문단에서 확인할 수 있어요.","edits":[{"start":35,"end":43,"before":"이익을 얻는다.","after":"손해를 본다."}]},"글쓴이가 걱정하는 관객은 암표를 살 돈이 충분한 사람이다.":{"reason":"바르게 고치면: 글쓴이가 걱정하는 관객은 암표를 살 돈이 부족한 사람이다.\n암표상이 먼저 표를 가져가면 뒤에서 기다리는 관객이 받을 표는 줄어들어요. 돈이 부족한 관객은 나중에 암표를 살 수도 없어요.\n10문단에서 확인할 수 있어요.","edits":[{"start":23,"end":27,"before":"충분한 ","after":"부족한 "}]},"암표상이 표를 한 장도 받지 않아도, 암표상 때문에 뒤의 관객이 받을 표가 줄어든다.":{"reason":"바르게 고치면: 암표상이 표를 먼저 받아 가면, 암표상 때문에 뒤의 관객이 받을 표가 줄어든다.\n암표상이 먼저 표를 가져가면 뒤에서 기다리는 관객이 받을 표는 줄어들어요. 돈이 부족한 관객은 나중에 암표를 살 수도 없어요.\n10문단에서 확인할 수 있어요.","edits":[{"start":8,"end":21,"before":"한 장도 받지 않아도, ","after":"먼저 받아 가면, "}]},"글쓴이가 걱정하는 관객은 암표상보다 먼저 표를 받은 사람이다.":{"reason":"바르게 고치면: 글쓴이가 걱정하는 관객은 암표상 뒤에서 표를 기다리는 사람이다.\n암표상이 먼저 표를 가져가면 뒤에서 기다리는 관객이 받을 표는 줄어들어요. 돈이 부족한 관객은 나중에 암표를 살 수도 없어요.\n10문단에서 확인할 수 있어요.","edits":[{"start":14,"end":23,"before":"암표상보다 먼저 ","after":"암표상 뒤에서 "},{"start":26,"end":29,"before":"받은 ","after":"기다리는 "}]}},"pageSpecificReasons":true,"evidence":{"title":"암표 확보가 뒤 사람에게 미치는 영향","statement":"암표상이나 대신 줄을 선 사람이 표를 먼저 받아 가면, 뒤에서 기다리던 관객은 무료 표를 못 받을 수 있다. 암표를 살 돈도 없다면 손해를 본다.","explanation":"암표상이 먼저 표를 가져가면 뒤에서 기다리는 관객이 받을 표는 줄어들어요. 돈이 부족한 관객은 나중에 암표를 살 수도 없어요.\n10문단에서 확인할 수 있어요.","valid":["L10:4"],"sources":[{"id":"L10","title":"줄 서기를 돈으로 살 수 있을까","label":"10문단","sentences":[{"id":"L10:1","text":"아마도 대변인의 의도는 암표 거래는 125달러를 지불할 만한 경제적 여유가 없는 사람에게 불공정한 행위라는 것이리라.","paragraph":0,"memberIds":["L10:1"],"topic":"대변인이 하고 싶은 말은 아마 이것일 것이다. \"암표는 125달러를 낼 돈이 없는 사람에게 불공평하다.\""},{"id":"L10:2","text":"보통 사람은 그만큼 불리하게 되어 입장권을 손에 넣기가 더욱 힘들어진다.","paragraph":0,"memberIds":["L10:2"],"topic":"평범한 사람은 그만큼 불리해져서 표를 구하기가 더 어려워진다."},{"id":"L10:3","text":"이 주장은 설득력이 있다.","paragraph":0,"memberIds":["L10:3"],"topic":"필자는 “암표 거래는 돈이 부족한 사람에게 불공정하다”는 주장에 설득력이 있다고 본다."},{"id":"L10:4","text":"돈을 받고 대신 줄을 선 사람이나 암표상이 입장권을 확보했다면 그 뒤에 서 있던 사람, 즉 암표 가격을 지불할 만한 경제적 여유가 없는 사람은 손해를 본다.","paragraph":0,"memberIds":["L10:4"],"topic":"줄 알바나 암표상이 앞에서 표를 가져가 버리면, 그 뒤에 선 사람은 표를 못 받는다. 그 사람은 비싼 암표를 살 돈도 없다. 그러니 손해를 본다."}]}]},"editorSourceVersion":"7969b31b23d75ed638ec852dad3de44ec6bd9b393ca6547228dfa004a729d2e3"}]},{"name":"U22-44 · 입장료·암표와 공공 축제의 변질","items":[{"paragraphCount":1,"readingLabel":"18문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 18문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 18문단]\n퍼블릭 시어터는 무료 야외 공연을 대중의 축제이자 일종의 시민 축하 행사로 생각한다. 말하자면 시(市)가 스스로에게 베푸는 선물인 셈이다. 물론 좌석 수는 한정되어 있다. 정해진 저녁 시간에 시민 전체가 참석할 수는 없기 때문이다. 하지만 퍼블릭 시어터의 취지는 관람료 지불 능력과 전혀 관계없이 누구나 평등하게 셰익스피어 공연을 무료로 관람할 수 있게 하는 것이다. 본래 선물이어야 하는 행사로 입장료를 받거나 암표상이 이득을 취하게 허용하는 일은 이러한 취지에 어긋난다. 이는 공공의 축제를 돈벌이, 즉 사적 이익을 취득하기 위한 도구로 바꾸는 행위다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["인과"],"id":"U22-44-S1","type":"mc","sent":"18문단의 내용과 맞는 설명은?","options":["입장료를 받거나 암표로 돈을 벌게 하면 시민에게 선물하려던 목적을 잘 이룰 수 있다.","암표상이 돈을 버는 일은 모든 시민에게 똑같은 기회를 주는 방법이다.","입장료 없이 무료로 제공하는 일도 돈을 받고 파는 일과 같다.","입장료를 받거나 암표로 돈을 벌게 하면 시민 모두의 축제가 개인의 돈벌이가 된다. 시민들에게 무료 공연을 선물하려던 목적에 어긋난다.","글쓴이는 암표상이 돈을 벌어도 시민이 함께하는 축제의 의미가 지켜진다고 본다."],"answer":"입장료를 받거나 암표로 돈을 벌게 하면 시민 모두의 축제가 개인의 돈벌이가 된다. 시민들에게 무료 공연을 선물하려던 목적에 어긋난다.","why":"무료 공연의 목적은 시민들이 함께 즐기는 것이에요. 암표를 팔아 돈을 벌면 시민 모두를 위한 축제가 개인이 이익을 챙기는 일이 돼요.\n18문단에서 확인할 수 있어요.","choiceReviews":{"입장료를 받거나 암표로 돈을 벌게 하면 시민 모두의 축제가 개인의 돈벌이가 된다. 시민들에게 무료 공연을 선물하려던 목적에 어긋난다.":{"reason":"무료 공연의 목적은 시민들이 함께 즐기는 것이에요. 암표를 팔아 돈을 벌면 시민 모두를 위한 축제가 개인이 이익을 챙기는 일이 돼요.\n18문단에서 확인할 수 있어요.","edits":[]},"입장료를 받거나 암표로 돈을 벌게 하면 시민에게 선물하려던 목적을 잘 이룰 수 있다.":{"reason":"바르게 고치면: 입장료를 받거나 암표로 돈을 벌게 하면 시민에게 선물하려던 목적에 어긋난다.\n무료 공연의 목적은 시민들이 함께 즐기는 것이에요. 암표를 팔아 돈을 벌면 시민 모두를 위한 축제가 개인이 이익을 챙기는 일이 돼요.\n18문단에서 확인할 수 있어요.","edits":[{"start":33,"end":47,"before":"목적을 잘 이룰 수 있다.","after":"목적에 어긋난다."}]},"암표상이 돈을 버는 일은 모든 시민에게 똑같은 기회를 주는 방법이다.":{"reason":"바르게 고치면: 암표상이 돈을 버는 일은 시민 모두를 위한 축제를 개인의 돈벌이로 바꾸는 일이다.\n무료 공연의 목적은 시민들이 함께 즐기는 것이에요. 암표를 팔아 돈을 벌면 시민 모두를 위한 축제가 개인이 이익을 챙기는 일이 돼요.\n18문단에서 확인할 수 있어요.","edits":[{"start":14,"end":38,"before":"모든 시민에게 똑같은 기회를 주는 방법이다.","after":"시민 모두를 위한 축제를 개인의 돈벌이로 바꾸는 일이다."}]},"입장료 없이 무료로 제공하는 일도 돈을 받고 파는 일과 같다.":{"reason":"바르게 고치면: 무료로 제공하는 일은 돈을 받고 파는 일과 다르다.\n무료 공연의 목적은 시민들이 함께 즐기는 것이에요. 암표를 팔아 돈을 벌면 시민 모두를 위한 축제가 개인이 이익을 챙기는 일이 돼요.\n18문단에서 확인할 수 있어요.","edits":[{"start":0,"end":7,"before":"입장료 없이 ","after":""},{"start":16,"end":19,"before":"일도 ","after":"일은 "},{"start":31,"end":34,"before":"같다.","after":"다르다."}]},"글쓴이는 암표상이 돈을 벌어도 시민이 함께하는 축제의 의미가 지켜진다고 본다.":{"reason":"바르게 고치면: 글쓴이는 암표상이 돈을 벌면 시민이 함께하는 축제의 의미가 훼손된다고 본다.\n무료 공연의 목적은 시민들이 함께 즐기는 것이에요. 암표를 팔아 돈을 벌면 시민 모두를 위한 축제가 개인이 이익을 챙기는 일이 돼요.\n18문단에서 확인할 수 있어요.","edits":[{"start":13,"end":17,"before":"벌어도 ","after":"벌면 "},{"start":34,"end":40,"before":"지켜진다고 ","after":"훼손된다고 "}]}},"pageSpecificReasons":true,"evidence":{"title":"입장료·암표와 공공 축제의 변질","statement":"입장료를 받거나 암표로 돈을 벌게 하면 시민 모두의 축제가 개인의 돈벌이가 된다. 시민들에게 무료 공연을 선물하려던 목적에 어긋난다.","explanation":"무료 공연의 목적은 시민들이 함께 즐기는 것이에요. 암표를 팔아 돈을 벌면 시민 모두를 위한 축제가 개인이 이익을 챙기는 일이 돼요.\n18문단에서 확인할 수 있어요.","valid":["L18:5","L18:6","L18:7"],"sources":[{"id":"L18","title":"줄 서기를 돈으로 살 수 있을까","label":"18문단","sentences":[{"id":"L18:1","text":"퍼블릭 시어터는 무료 야외 공연을 대중의 축제이자 일종의 시민 축하 행사로 생각한다.","paragraph":0,"memberIds":["L18:1"],"topic":"극장은 이 무료 공연을 모두의 축제, 시민들의 잔치로 여긴다."},{"id":"L18:2","text":"말하자면 시(市)가 스스로에게 베푸는 선물인 셈이다.","paragraph":0,"memberIds":["L18:2"],"topic":"말하자면 도시가 시민들, 곧 자기 자신에게 주는 선물이다."},{"id":"L18:3","text":"물론 좌석 수는 한정되어 있다.","paragraph":0,"memberIds":["L18:3"],"topic":"물론 자리는 정해져 있다."},{"id":"L18:4","text":"정해진 저녁 시간에 시민 전체가 참석할 수는 없기 때문이다.","paragraph":0,"memberIds":["L18:4"],"topic":"그날 저녁에 모든 시민이 다 올 수는 없으니까."},{"id":"L18:5","text":"하지만 퍼블릭 시어터의 취지는 관람료 지불 능력과 전혀 관계없이 누구나 평등하게 셰익스피어 공연을 무료로 관람할 수 있게 하는 것이다.","paragraph":0,"memberIds":["L18:5"],"topic":"하지만 극장이 원래 하려던 것(취지)은 돈이 있든 없든 누구나 똑같이 공짜로 공연을 보게 하는 것이다."},{"id":"L18:6","text":"본래 선물이어야 하는 행사로 입장료를 받거나 암표상이 이득을 취하게 허용하는 일은 이러한 취지에 어긋난다.","paragraph":0,"memberIds":["L18:6"],"topic":"원래 선물이어야 할 행사에서 입장료를 받거나 암표상이 돈을 벌게 놔두면, 그 목적과 어긋난다."},{"id":"L18:7","text":"이는 공공의 축제를 돈벌이, 즉 사적 이익을 취득하기 위한 도구로 바꾸는 행위다.","paragraph":0,"memberIds":["L18:7"],"topic":"그건 모두의 축제를 개인의 돈벌이 수단(사적 이익의 도구)으로 바꿔 버리는 일이다."}]}]},"editorSourceVersion":"e5dac5f2c1ad59178c4dfb7efffc9c920c5fbb1a761866487a7d1e3d0ecb2c1e"}]}]};})(window);
